class ProcStatTest : public ::testing::Test
{
  public:
    ProcStatTest(){
    }

    /**Handy for testing sums, each jiffy increases by a factor to avoid any accidental sum from wrong values.*/
    ProcStat::CpuJiffies jiffiesSumFixture()
    {
      ProcStat::CpuJiffies jiffies;
      jiffies.user=1;
      jiffies.nice=10;
      jiffies.system=100;
      jiffies.idle=1000;
      jiffies.iowait=10000;
      jiffies.irq=100000;
      jiffies.softirq=1000000;
      return jiffies;
    }
};

TEST_F(ProcStatTest, parseCpuLine_ReturnsCpuLineWithValidJiffies)
{
  string line="cpu  14363537 24188 4071493 241034967 995798 736353 1943565 0 0 0";
  ProcStat::CpuJiffies jiffies = ProcStat::lineToJiffies(line);
  ASSERT_EQ(jiffies.user,14363537);
  ASSERT_EQ(jiffies.nice,24188);
  ASSERT_EQ(jiffies.system,4071493);
  ASSERT_EQ(jiffies.idle,241034967);
  ASSERT_EQ(jiffies.iowait,995798);
  ASSERT_EQ(jiffies.irq,736353);
  ASSERT_EQ(jiffies.softirq,1943565);
}

TEST_F(ProcStatTest, totalJiffies_sumsUpCorrectly)
{
  long total = ProcStat::totalJiffies(jiffiesSumFixture());
  ASSERT_EQ(total,1111111);
}

TEST_F(ProcStatTest, workJiffies_sumsUpCorrectly)
{
  long total = ProcStat::workJiffies(jiffiesSumFixture());
  ASSERT_EQ(total,111);
}

TEST_F(ProcStatTest, workJiffies_cpuUsage)
{
  ProcStat::CpuJiffies first;
  first.user = 0;
  first.nice=0;
  first.system=0;
  first.idle=0;
  first.iowait=0;
  first.irq=0;
  first.softirq=0;
  ProcStat::CpuJiffies second;
  second.user = 1;
  second.nice=0;
  second.system=0;
  second.idle=0;
  second.iowait=0;
  second.irq=0;
  second.softirq=9;
  int cpu = ProcStat::cpuUsage(first,second);
  ASSERT_EQ(cpu,10);
}